<?php
namespace Tests\Feature; use Illuminate\Database\Eloquent\Relations\Relation; use Illuminate\Support\Facades\Schema; use Tests\TestCase;
class TrainingCap2ArchitectureTest extends TestCase { public function test_cap2_has_sessions_and_reuses_transversal_attendance():void{$this->assertTrue(Schema::hasColumns('training_sessions',['company_id','training_program_item_id','attendance_event_id','actual_duration_minutes','called_snapshot']));$this->assertTrue(Schema::hasColumns('attendance_participants',['name_snapshot','role_snapshot','department_snapshot','invitation_status','added_after_freeze','excluded_at']));$this->assertSame(\App\Models\TrainingSession::class,Relation::getMorphedModel('training_session'));} public function test_cap2_does_not_duplicate_qr_signatures_or_attendance():void{$this->assertFalse(Schema::hasTable('training_attendances'));$this->assertFalse(Schema::hasTable('training_signatures'));$this->assertFalse(Schema::hasTable('training_qr_codes'));$this->assertTrue(Schema::hasTable('attendance_signatures'));} public function test_dates_and_evidence_structures_are_present():void{$this->assertTrue(Schema::hasColumns('training_sessions',['scheduled_start_at','scheduled_end_at','actual_start_at','actual_end_at']));$this->assertTrue(Schema::hasTable('training_session_evidences'));$this->assertSame('America/Bogota',config('app.timezone'));} }
